#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    // Define a regex pattern to match markdown syntax
    std::regex pattern(R"(^#([0-9]+)\s*(.*?)$)");

    // Create a match object to store the matched text
    std::smatch match;

    // Search for the pattern in the markdown text
    while (std::regex_search(markdown, match, pattern)) {
        // Replace the matched text with an HTML equivalent
        std::string html = "<h" + match[1].str() + ">" + match[2].str() + "</h" + match[1].str() + ">";

        // Remove the matched text from the markdown text
        markdown.replace(html.length(), html.length());
    }

    // Return the converted HTML text
    return markdown;
}
```

